// модуль об'єкта ДОКУМЕНТА, ЩО ВВОДИТЬСЯ (тут — надходження із замовлення)
Procedure Filling(Source, StandartProcessing)
{
    If (Not ValueIsFilled(Source)) {
        Return;                        // просто новий документ: лише типові значення
    }
    // шапка за іменами; рядки — з того, що за замовленням ще відкрито
    Counterparty = Source.Counterparty;
    Warehouse = Source.Warehouse;
    foreach (line In Source.Goods) {
        var row = Goods.Add();
        row.Item = line.Item;
        row.Quantity = line.Quantity;
    }
}

